    await page.setRequestInterception(true);
    page.on('request', req => {
      const t = req.resourceType(); const u = req.url();
      if (['image', 'media', 'font', 'stylesheet'].includes(t) && !/login\.sonepar\.fr/.test(u)) return req.abort();
      if (/google-analytics|googletagmanager|doubleclick|facebook|hotjar|onetrust|cookielaw|contentsquare|dynatrace|clarity|bing\.com|adobedtm|demdex|abtasty|algolia-insights/i.test(u)) return req.abort();
      req.continue();
