    await page.goto('https://www.sonepar.fr/fr-fr', { waitUntil: 'networkidle2' });
    const cb = await page.$('#onetrust-reject-all-handler');
    if (cb) { await cb.click().catch(() => {}); await sleep(800); }
    out.etapes.push('accueil');
